mapper.select:
select product_id, sum(quantity) as popularity from (
select i.product_id, coalesce(i.quantity, 1) as quantity from t_order o inner join t_order_item i on i.order_id = o.order_id where o.status in (1, 2, 3) and coalesce(o.refund_status, 0) <> 2 and coalesce(o.pay_time, o.finish_time, o.create_time) >= #{cutoffTime} and (i.spec is null or i.spec not like '赠品%')
select i.product_id, coalesce(i.quantity, 1) as quantity from t_scan_order o inner join t_scan_order_item i on i.order_id = o.order_id where o.status in (2, 3, 4) and coalesce(o.refund_status, 0) <> 2 and coalesce(o.pay_time, o.finish_time, o.create_time) >= #{cutoffTime}
select null as product_id, 0 as quantity where 1 = 0
) recent_orders group by product_id order by popularity desc, product_id asc

select count(*)
from t_user_behavior_event
where user_id = #{userId}
  and event_time >= #{cutoffTime}
